#include <cctype>
#include <map>
#include <sstream>
#include <string>
#include <vector>

struct Kdnet { std::string host; int port{ 0 }; std::string key; };

namespace
{
    std::vector<std::string> split(const std::string& s, char sep)
    {
        std::vector<std::string> parts;
        std::string part;
        for (char c : s) { if (c == sep) { parts.push_back(part); part.clear(); } else part += c; }
        parts.push_back(part);
        return parts;
    }

    bool allDigits(const std::string& s)
    {
        if (s.empty()) return false;
        for (char c : s) if (!std::isdigit(static_cast<unsigned char>(c))) return false;
        return true;
    }

    bool validHost(const std::string& h)
    {
        const auto parts{ split(h, '.') };
        if (parts.size() != 4) return false;
        for (const auto& p : parts)
        {
            if (!allDigits(p) || p.size() > 3 || (p.size() > 1 && p[0] == '0') || std::stoi(p) > 255) return false;
        }
        return true;
    }

    bool validKey(const std::string& k)
    {
        const auto parts{ split(k, '.') };
        if (parts.size() != 4) return false;
        for (const auto& p : parts)
        {
            if (p.empty() || p.size() > 13) return false;
            for (char c : p) if (!(std::isdigit(static_cast<unsigned char>(c)) || (c >= 'a' && c <= 'z'))) return false;
        }
        return true;
    }
}

bool parseSettings(const std::string& text, Kdnet& out, std::string& error)
{
    std::map<std::string, std::string> values;
    std::istringstream in{ text };
    for (std::string pair; in >> pair;)
    {
        const auto eq{ pair.find('=') };
        const std::string name{ eq == std::string::npos ? "" : pair.substr(0, eq) };
        if (eq == std::string::npos || (name != "host" && name != "port" && name != "key") || values.count(name))
        {
            error = "bad setting: " + pair;
            return false;
        }
        values[name] = pair.substr(eq + 1);
    }
    for (const char* need : { "host", "port", "key" })
        if (!values.count(need)) { error = std::string("missing ") + need; return false; }
    if (!validHost(values["host"])) { error = "bad host"; return false; }
    const std::string& port{ values["port"] };
    if (!allDigits(port) || port.size() > 5 || std::stoi(port) < 50000 || std::stoi(port) > 50039) { error = "port must be 50000-50039"; return false; }
    if (!validKey(values["key"])) { error = "bad key"; return false; }
    out = { values["host"], std::stoi(port), values["key"] };
    return true;
}

std::string hostCommand(const Kdnet& k)
{
    return "windbg -k net:port=" + std::to_string(k.port) + ",key=" + k.key;
}

unitTests:
TEST("good settings") {
    Kdnet k; std::string err;
    CHECK(parseSettings("key=1a.2b.3c.4d  host=192.168.1.10 port=50005", k, err)); CHECK_EQ(k.host, std::string("192.168.1.10")); CHECK_EQ(k.port, 50005);
    CHECK_EQ(hostCommand(k), std::string("windbg -k net:port=50005,key=1a.2b.3c.4d"));
    CHECK(parseSettings("host=0.0.0.0 port=50039 key=z.0.abcdefghijklm.9", k, err));
}
TEST("errors in order") {
    Kdnet k; std::string err;
    CHECK(!parseSettings("host=1.2.3.4 port", k, err)); CHECK_EQ(err, std::string("bad setting: port"));
    CHECK(!parseSettings("host=1.2.3.4 host=1.2.3.5", k, err)); CHECK_EQ(err, std::string("bad setting: host=1.2.3.5"));
    CHECK(!parseSettings("speed=fast", k, err)); CHECK_EQ(err, std::string("bad setting: speed=fast"));
    CHECK(!parseSettings("key=1.2.3.4", k, err)); CHECK_EQ(err, std::string("missing host"));
    CHECK(!parseSettings("host=1.2.3.4 key=1.2.3.4", k, err)); CHECK_EQ(err, std::string("missing port"));
    CHECK(!parseSettings("host=1.2.3 port=50000 key=1.2.3.4", k, err)); CHECK_EQ(err, std::string("bad host"));
    CHECK(!parseSettings("host=1.2.3.04 port=50000 key=1.2.3.4", k, err)); CHECK_EQ(err, std::string("bad host"));
    CHECK(!parseSettings("host=1.2.3.256 port=50000 key=1.2.3.4", k, err)); CHECK_EQ(err, std::string("bad host"));
    CHECK(!parseSettings("host=1.2.3.4 port=50040 key=1.2.3.4", k, err)); CHECK_EQ(err, std::string("port must be 50000-50039"));
    CHECK(!parseSettings("host=1.2.3.4 port=5x000 key=1.2.3.4", k, err)); CHECK_EQ(err, std::string("port must be 50000-50039"));
    CHECK(!parseSettings("host=1.2.3.4 port=50000 key=1.2.3", k, err)); CHECK_EQ(err, std::string("bad key"));
    CHECK(!parseSettings("host=1.2.3.4 port=50000 key=1.2.3.A", k, err)); CHECK_EQ(err, std::string("bad key"));
    CHECK(!parseSettings("host=1.2.3.4 port=50000 key=1.2..4", k, err)); CHECK_EQ(err, std::string("bad key"));
}

